   if(taken[0]&&PorterWork.active(x)&&callbacks[0]++%20==0){Warehouses.tick(t.l,t.e,20);Population.assign(t.e,1);integrity[0]&=!CartWolves.relieved(t.s.id())&&Population.slots(t.s,t.store)==2&&t.s.resident(t.porter.getUUID()).profession()==Profession.PORTER&&t.s.workplace(t.porter.getUUID())!=null&&t.s.workplace(t.porter.getUUID()).id().equals(t.store.id())&&PorterWork.inspect(t.l,t.porter.getUUID()).getUUID("id").equals(job[0]);}
