   if(frames[0]++%20==0){physicalTick(t);var x=WarehouseTrips.inspect(t.l,t.wolf.getUUID());if(paid[0]==null&&!WarehouseTrips.custody(t.l,x).isEmpty()){paid[0]=x.copy();integrity[0]&=!x.getString("stage").equals("fetch")&&WarehouseTrips.custody(t.l,x).size()==1&&WarehouseTrips.custody(t.l,x).get(0).getCount()==32;WarehouseTrips.forget(t.l.getServer());integrity[0]&=WarehouseTrips.inspect(t.l,t.wolf.getUUID()).equals(paid[0]);}if(paid[0]!=null&&!WarehouseTrips.active(x)){finished[0]=true;t.wolf.setNoAi(true);}}
